update public.cell_groups
set leader_participant_id = case id
  when '30000000-0000-4000-8000-000000000001' then '11000000-0000-4000-8000-000000000001'::uuid
  when '30000000-0000-4000-8000-000000000002' then '11000000-0000-4000-8000-000000000018'::uuid
  when '30000000-0000-4000-8000-000000000003' then '11000000-0000-4000-8000-000000000022'::uuid
  when '30000000-0000-4000-8000-000000000004' then '11000000-0000-4000-8000-000000000031'::uuid
  else leader_participant_id
end
where id in (
  '30000000-0000-4000-8000-000000000001',
  '30000000-0000-4000-8000-000000000002',
  '30000000-0000-4000-8000-000000000003',
  '30000000-0000-4000-8000-000000000004'
);

